export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "21:30。M-00 醫療區外側走廊。紗英睡了。呼吸治療師留在裡面監測。其他人退到走廊。", background: Background.Chapter_21_Ch21_Act8_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪站在觀察窗前。她沒有坐下。她的手按在玻璃上。玻璃很涼。", background: Background.Chapter_21_Ch21_Act8_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯R4。作者是我。⋯⋯未來的我。⋯⋯寫了一整套方案。⋯⋯然後說不要送回來。⋯⋯為什麼。⋯⋯為什麼寫了又不送回來。⋯⋯如果方案是對的——為什麼不送。⋯⋯如果方案是錯的——為什麼寫。", background: Background.Chapter_21_Ch21_Act8_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "然後——", background: Background.Chapter_21_Ch21_Act8_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "不是睡著。不是暈。是什麼東西從很遠的地方撞過來。像白光。但不是白光。比白光更碎。更短。更安靜。", background: Background.Chapter_21_Ch21_Act8_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的手按在一張圖上。不是觀察窗。是一張平面圖。鏡島。東京灣人工島。KAGAMI-01 的節點位置在圖上標著。她的手指壓在某一個點上。", background: Background.Chapter_21_Ch21_Act8_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "文件角落。一個標記。R4。手寫的。是她自己的字。", background: Background.Chapter_21_Ch21_Act8_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "圖上有一個名字被圈起來。紅筆。圈得很重。第一順位。悠真。", background: Background.Chapter_21_Ch21_Act8_S1 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "然後是聲音。她自己的聲音。不是現在的聲音。是某一個還沒有到達的時間裡的聲音。很累。很啞。但很確定。", background: Background.Chapter_21_Ch21_Act8_S1 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "不要把整份方案送回去。", background: Background.Chapter_21_Ch21_Act8_S1, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "只留下我必須拒絕它的理由。", background: Background.Chapter_21_Ch21_Act8_S1, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "21:34。走廊。觀察窗。玻璃。她的手還按在上面。但手心是濕的。額頭也是。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部已經站在她旁邊。他扶住她的肩膀。沒有用力。只是讓她不倒。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "澪。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯我看見了。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "什麼？", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "鏡島。平面圖。KAGAMI-01。⋯⋯文件角落寫著 R4。⋯⋯悠真的名字被圈起來。第一順位。⋯⋯我聽到自己在說話。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "不要把整份方案送回去。⋯⋯只留下我必須拒絕它的理由。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的聲音很平。像在讀一份剛才還在眼前的文件。但文件已經不在了。只剩聲音的殘影。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "⋯⋯主觀前向回聲。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "我知道。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "主觀回聲不能作客觀證據。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "我知道。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他沒有放手。但他也沒有退讓。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "妳聽到的、看到的——可能是託管回聲。也可能是文件暗示、疲勞、自我生成的記憶。⋯⋯我不能把它寫進報告。不能當證據。不能當客觀事實。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "我知道。⋯⋯可是我聽到了。是我自己的聲音。⋯⋯不是別人的。是我。在某一條還沒有發生的未來裡。⋯⋯我寫了 R4。然後我要求不要把 R4 送回來。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "這正是它不能當證據的原因。⋯⋯因為它可能是真的。也可能是妳想它是真的。⋯⋯我分不出來。妳也分不出來。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪沒有反駁。因為他是對的。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "外部醫師走過來。他看著澪的臉色。看著她額頭上的汗。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "血壓？脈搏？", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部鬆開手。澪靠著牆。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯沒事。不是癲癇。不是昏厥。⋯⋯是回聲。很短。幾秒。已經過了。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "我需要記錄。主觀症狀。持續時間。內容由妳口述。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "可以。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她口述了。外部醫師寫下來。每一個字。鏡島。KAGAMI-01。R4。悠真。第一順位。兩句話。他沒有加註解。只記錄。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "獨立神經心理專業人員在旁邊。她也記了。但她加了一行。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.NeuropsychProfessional, character: "獨立神經心理專業人員", dialogue: "主觀前向回聲。來源未定。不能作為客觀證據使用。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪看著那行字。她點了一下頭。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯他們是對的。⋯⋯主觀回聲不能當證據。⋯⋯可是那個聲音是我的。⋯⋯那個字跡是我的。⋯⋯那條未來裡的我——寫了方案。然後拒絕把方案送回來。⋯⋯只留下拒絕的理由。⋯⋯不是留下答案。是留下拒絕答案的自由。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "22:05。紗英醒了。不是完全清醒。是眼睛又開了一半。她看向門口。看向走廊。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "呼吸治療師確認了數字。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.RespiratoryTherapist, character: "呼吸治療師", dialogue: "血氧九十三。呼吸頻率十八。穩定。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "紗英的視線移動。看向溝通板。呼吸治療師看了外部醫師一眼。外部醫師點頭。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "板子被調回來。螢幕亮了。沒有快捷選項。沒有提示。字母矩陣。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "游標移動。很慢。一個字母。一個字母。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "M。I。O。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕上出現一個名字。MIO。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯她又叫了我的名字。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "游標繼續。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "S。A。W。　C。O。S。T。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "MIO　SAW　COST", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯看見代價。⋯⋯我看見了代價。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪的喉嚨動了一下。她看著螢幕。她看著母親。紗英的眼睛沒有離開板子。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯在妳記得的未來裡——R4 的作者看過代價嗎？", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "紗英沒有回應那句話。她的眼睛在板子上。游標繼續移動。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "A。C。C。E。P。T。E。D。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "MIO　SAW　COST　ACCEPTED", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯她仍然接受了嗎？", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "游標移動。最後一個字。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "O。N。C。E。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "MIO　SAW　COST　ACCEPTED　ONCE", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "游標停了。紗英的眼睛閉上。呼吸治療師看著監測器。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.RespiratoryTherapist, character: "呼吸治療師", dialogue: "血氧九十。呼吸頻率二十三。中止。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "中止。讓她休息。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "板子被調暗。紗英的呼吸慢慢降下來。她睡著了。或者回到了那個半昏迷的地方。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "走廊裡很安靜。外部醫師把螢幕上的字拍下來。然後他看著獨立神經心理專業人員。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "醫療翻譯。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.NeuropsychProfessional, character: "獨立神經心理專業人員", dialogue: "在紗英記得的那條可能未來裡，澪曾看見代價，仍接受過一次。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她頓了一下。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.NeuropsychProfessional, character: "獨立神經心理專業人員", dialogue: "這是臨床觀察記錄。不是客觀事實陳述。來源未定。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪站在觀察窗前。她聽到了那句翻譯。每一個字都聽到了。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯看見代價。⋯⋯仍然接受。⋯⋯一次。⋯⋯未來的我。看見了代價。知道會付出什麼。⋯⋯還是接受了。⋯⋯然後——之後——她要求不要把方案送回來。⋯⋯不是一開始就拒絕。是接受了之後才拒絕。⋯⋯她先走過那條路。然後退回來。然後把路堵住。⋯⋯只留下拒絕的理由。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "走廊那端。凪原站在觀察窗的另一側。她一直站在那裡。她聽到了所有字。透過玻璃。透過門縫。透過牆。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的臉沒有變。銀框眼鏡。白袍。脊椎沒有彎。像從走進這棟建築到現在，她的姿勢就沒有變過一次。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "但她的手動了。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "很小的一個動作。左手。從口袋裡出來。碰了一下眼鏡的鏡框。然後回去。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "不是調整眼鏡。是碰到之後停了一下。像在確認什麼還在。然後鬆開。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯代價。⋯⋯接受。⋯⋯她動了。⋯⋯凪原動了。⋯⋯她聽到「代價」和「接受」的時候——她的手碰了眼鏡。⋯⋯她知道。⋯⋯她知道代價是什麼。⋯⋯她不解釋。她從來不解釋。⋯⋯但她的手知道。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部也看到了。他看了凪原一眼。然後他看著澪。他沒有說話。但他把那個動作記下來了。澪知道。因為他的眼睛停了一秒。只有一秒。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "22:40。走廊。所有人都累了。外部醫師在寫記錄。獨立神經心理專業人員在封存觀察筆記。呼吸治療師在裡面盯著監測器。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部走到澪旁邊。他的聲音很低。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "⋯⋯她對「代價」和「接受」有反應。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "我看到了。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "不寫進報告。⋯⋯但我知道。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "她知道代價是什麼。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "可能。⋯⋯也可能只是疲勞。⋯⋯也可能只是習慣動作。⋯⋯我不能把「她碰了眼鏡」當成她知道 R4 代價的證據。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "我知道。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "⋯⋯但我不會忘記。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪看著他。他的臉很疲憊。眼下的陰影很深。但他的眼睛是清醒的。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯他開始把「知道代價的澪」和所有其他決策者一樣看待了。⋯⋯不是因為他懷疑我。⋯⋯是因為他在那一秒裡看見了——做出決定的人可能是自己。⋯⋯不是凪原。不是琴音。⋯⋯是我。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "23:00。走廊更安靜了。換班的腳步聲從遠處傳來。設備的嗡聲沒有停。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪靠著牆。她看著觀察窗裡的母親。紗英睡著了。胸口很慢地起伏。呼吸器的節奏沒有變。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯我一直以為——缺少完整答案是能力的缺陷。⋯⋯我查不夠快。記不夠多。拼不夠完整。⋯⋯所以我才沒有全部答案。⋯⋯可是——⋯⋯如果不是缺陷呢。⋯⋯如果某條由下一回聲窗送回警告的可能未來裡——知道代價的我——曾刻意要求母親不要把答案送回來。⋯⋯只把重新選擇的自由留給我。⋯⋯不是因為答案不重要。⋯⋯是因為拿到完整答案的我——接受了代價。⋯⋯接受了。然後後悔了。⋯⋯然後把答案堵在門外。只留下拒絕的權利。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她閉上眼睛。額頭靠著玻璃。玻璃很涼。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯未來的我看見了代價。仍然接受過一次。⋯⋯現在的我還不知道代價是什麼。⋯⋯可是我必須決定——在不知道代價的情況下——我要不要走那條路。⋯⋯還是拒絕。⋯⋯像她一樣拒絕。⋯⋯在還來得及的時候。", background: Background.Chapter_21_Ch21_Act8_S2, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "23:10。M-00 醫療區。走廊。觀察窗。呼吸器與發聲閥的聲音都很慢。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "目前這條時間線裡，第四版從來沒有被寫下。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "可母親記得一條由下一個星期一送回來的未來。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "在那條未來裡，澪看見了代價，仍然接受過一次。", background: Background.Chapter_21_Ch21_Act8_S2 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "距下一次星期一 06:13——約四日七小時三分鐘。", background: Background.Chapter_21_Ch21_Act8_S2 },
];
